def enable_libraries_with_podcasts(apps, schema_editor):
    Course = apps.get_model("app_portal", "Course")
    apps.get_model("app_portal", "EntraGroup").objects.filter(
        Exists(Course.objects.filter(group=OuterRef("pk")))
        | Exists(Course.objects.filter(shared_groups=OuterRef("pk")))
    ).update(status="enabled")


def name_groups_after_their_id(apps, schema_editor):
    EntraGroup = apps.get_model("app_portal", "EntraGroup")
    groups = list(EntraGroup.objects.filter(name=""))
    for group in groups:
        group.name = str(group.pk)
    EntraGroup.objects.bulk_update(groups, ["name"], batch_size=500)


def protect_audit_log(apps, schema_editor):
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute(APPEND_ONLY)


def unprotect_audit_log(apps, schema_editor):
    if schema_editor.connection.vendor == "postgresql":
        schema_editor.execute(REMOVE_APPEND_ONLY)


